'use strict';
const $ = (s, el=document) => el.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = v => v ? new Date(v).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}) : 'Not collected yet';
let user, page='instances', offset=0, records=[], groups=[], users=[], memberships=[], query='', state='', region='', renderID=0;
let cloudAccounts=[], selectedAccount=null, edsRegion='';
let edsRegions=[], edsQuery='', edsState='', edsBilling='', edsSort='name', edsDirection='asc';
let edsAllDesktops=[], edsFailedRegions=[], edsAssignmentsError='', edsUserQuery='', edsUserStatus='', edsUserAdmin='', edsUserSort='id', edsUserDirection='asc';
let edsCreateCatalog=null;
const names={instances:'Overview',eds:'EDS desktops',edsusers:'EDS users',accounts:'Cloud connections',groups:'Access policies',users:'Team members',activity:'Audit log',settings:'Workspace settings',api:'API reference'};
const actionIcons={
 start:'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5.5v13l10-6.5z" fill="currentColor"/></svg>',
 stop:'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="6" y="6" width="12" height="12" rx="1.5" fill="currentColor"/></svg>',
 manage:'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 7h10M18 7h2M4 17h2M10 17h10M14 4v6M7 14v6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><circle cx="14" cy="7" r="2" fill="currentColor"/><circle cx="7" cy="17" r="2" fill="currentColor"/></svg>'
};
async function api(path, options={}) {
 const response=await fetch('/api/v1'+path,{...options,headers:{'Content-Type':'application/json',...options.headers},credentials:'same-origin'});
 const data=await response.json();
 if(!response.ok){if(response.status===401 && path!='/auth/login') showLogin();throw new Error(data.error || 'Request failed');}return data;
}
const send=(path,method,body)=>api(path,{method,body:body===undefined?undefined:JSON.stringify(body)});
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function showLogin(){$('#app').hidden=true;$('#login').hidden=false;$('#modal').close();user=null;cloudAccounts=[];selectedAccount=null;}
async function showApp(){$('#login').hidden=true;$('#app').hidden=false;$('#workspace-name').textContent=user.workspace;$('#profile-name').innerHTML=esc(user.username)+'<small>'+esc(user.is_owner?'Workspace owner':user.role==='admin'?'Administrator':'Workspace member')+'</small>';$('#avatar').textContent=user.username[0].toUpperCase();document.querySelectorAll('.admin-only').forEach(e=>e.hidden=user.role!=='admin');try{await initializeCloudContext();}catch(e){toast(e.message);}render();}
async function initializeCloudContext(){cloudAccounts=(await api('/accounts')).data;const saved=localStorage.getItem('nexus.account.'+user.id)||localStorage.getItem('ccmp.account.'+user.id);selectedAccount=cloudAccounts.find(a=>String(a.id)===saved)||null;syncAccountSelector();}
function syncAccountSelector(){const control=$('#account-context');control.innerHTML='<option value="">All accessible accounts</option>'+cloudAccounts.map(a=>`<option value="${a.id}" ${selectedAccount?.id===a.id?'selected':''}>${esc(a.name)} · ${a.provider==='alibaba'?'Alibaba':'AWS'}</option>`).join('');renderProviderNavigation();}
function renderProviderNavigation(){const provider=selectedAccount?.provider;$('#compute-nav-label').textContent=provider==='alibaba'?'ECS instances':provider==='aws'?'EC2 instances':'Overview';$('#provider-context').textContent=selectedAccount?(provider.toUpperCase()+' / '+selectedAccount.name.toUpperCase()):'MULTI-CLOUD OVERVIEW';$('#provider-navigation').innerHTML=provider==='alibaba'?'<a href="#eds" data-page="eds"><span>▣</span>EDS desktops</a><a href="#edsusers" data-page="edsusers"><span>◎</span>EDS users</a>':'';}
function heading(eyebrow,title,description,actions=''){return `<div class="heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
const button=(label,action,kind='primary',id='',region='')=>`<button class="${kind}" data-action="${action}" data-id="${esc(id)}"${region?` data-region="${esc(region)}"`:''}>${label}</button>`;
const iconButton=(icon,label,action,kind,id,region='')=>`<button type="button" class="${kind} table-icon-button" data-action="${action}" data-id="${esc(id)}"${region?` data-region="${esc(region)}"`:''} aria-label="${esc(label)}" title="${esc(label)}">${actionIcons[icon]}</button>`;
const badge=v=>`<span class="badge ${esc(v)}">${esc(v)}</span>`;
const empty=(title,description,action='')=>`<div class="empty"><div class="empty-icon">☁</div><h3>${title}</h3><p>${description}</p>${action}</div>`;
const stat=(label,value,note,icon='▦')=>`<div class="stat"><div class="stat-top">${label}<i>${icon}</i></div><strong class="stat-value">${value}</strong><small>${note}</small></div>`;
const pager=(count)=>`<div class="pagination"><span>${count ? `${offset+1}–${offset+count}`:'0'} results · 50 per page</span><div><button class="secondary" data-action="prev" ${offset===0?'disabled':''}>←</button><button class="secondary" data-action="next" ${count<50?'disabled':''}>→</button></div></div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
async function render(){
 if(!user)return;const id=++renderID;page=location.hash.slice(1).split('?')[0]||'instances';if(!names[page]||((page==='eds'||page==='edsusers')&&selectedAccount?.provider!=='alibaba'))page='instances';$('#breadcrumb').textContent=names[page];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#content').innerHTML='<div class="loading">Loading workspace…</div>';
 try{let html='';if(page==='instances')html=await inventory();if(page==='eds')html=await edsDesktopsPage();if(page==='edsusers')html=await edsUsersPage();if(page==='accounts')html=await accountsPage();if(page==='groups')html=await groupsPage();if(page==='users')html=await usersPage();if(page==='activity')html=await activityPage();if(page==='settings')html=await settingsPage();if(page==='api')html=apiPage();if(id===renderID)$('#content').innerHTML=html;}catch(e){if(id===renderID)$('#content').innerHTML=empty('Unable to load this page',esc(e.message),button('Try again','reload','secondary'));}
}
async function inventory(){
 const p=new URLSearchParams({q:query,state,region,limit:'50',offset:String(offset)});if(selectedAccount)p.set('account_id',selectedAccount.id);
 const summaryParams=selectedAccount?'?account_id='+selectedAccount.id:'';
 const [items,summary]=await Promise.all([api('/instances?'+p),api('/summary'+summaryParams)]);records=items.data;
 const scope=selectedAccount?selectedAccount.name:'all accessible accounts';
 return heading('YOUR INFRASTRUCTURE, IN FOCUS',selectedAccount?(selectedAccount.provider==='alibaba'?'Alibaba ECS':'AWS EC2'):'Cloud overview',`Compute resources for ${esc(scope)}.`,`${button('↻ &nbsp; Refresh','reload','secondary')}${user.role==='admin'?button('Sync cloud ↗','sync'):''}`)+
 `<div class="hero"><div><span class="eyebrow">CONNECTED. ORGANIZED. UNDER CONTROL.</span><h2>A little clarity for your cloud.</h2><p>Track compute infrastructure across AWS and Alibaba Cloud from one isolated workspace.</p></div><div class="hero-art" aria-hidden="true"><span>☁</span><span>▦</span><span>⌘</span></div></div>`+
 `<div class="stat-grid">${stat('Total instances',summary.instances,'Across your accessible accounts')}${stat('Running',summary.running,'Instances currently online','◉')}${stat('Cloud accounts',summary.accounts,'Connected cloud accounts','☁')}${stat('Active regions',summary.regions,'Regions with discovered instances','◎')}</div>`+
 `<div class="panel"><div class="panel-heading"><div><h2>Compute inventory <span class="count">${summary.instances}</span></h2><p>Your cloud components, all in one place.</p></div><span class="muted">AWS EC2 · ALIBABA ECS</span></div><form id="filters" class="toolbar"><input name="q" aria-label="Search instances" placeholder="Search name, instance ID, IP, or account…" value="${esc(query)}"><select name="state" aria-label="Instance state"><option value="">All states</option>${['running','stopped','pending','starting','stopping','terminated'].map(s=>`<option ${s===state?'selected':''}>${s}</option>`).join('')}</select><input name="region" aria-label="Cloud region" placeholder="All regions" value="${esc(region)}"><button class="secondary">Filter</button></form>`+
 (records.length?table(['INSTANCE','STATUS','INSTANCE TYPE','REGION','ACCOUNT',''],records.map(i=>`<tr><td><strong>${esc(i.name||i.instance_id)}</strong><small>${esc(i.provider.toUpperCase())} · ${esc(i.instance_id)}</small></td><td>${badge(i.state)}</td><td>${esc(i.instance_type)}</td><td>${esc(i.region)}</td><td>${esc(i.account_name)}</td><td>${button('View ↗','details','text-button',i.id)}</td></tr>`)):empty(query||state||region?'No matching instances':'Your cloud starts here',query||state||region?'Try another search or clear your filters.':'Connect an AWS or Alibaba Cloud account, then sync to discover compute instances.',user.role==='admin'?button('Connect account ↗','add-account'):''))+pager(records.length)+'</div>';
}
function edsPath(resource,targetRegion=edsRegion){return `/accounts/${selectedAccount.id}/eds${resource}?region=${encodeURIComponent(targetRegion)}`;}
function preferredEDSRegion(){return selectedAccount?.regions?.[0]||selectedAccount?.discovered_regions?.[0]||'cn-hangzhou';}
const desktopRegion=d=>d.RegionId||edsRegion;
function edsRegionBar(allowAll=false){
 const selectedKnown=edsRegion==='all'||edsRegions.some(r=>r.id===edsRegion);
 const allOption=allowAll?`<option value="all" ${edsRegion==='all'?'selected':''}>All regions</option>`:'';
 const options=allOption+(selectedKnown?'':`<option value="${esc(edsRegion)}">${esc(edsRegion)} · selected</option>`)+edsRegions.map(r=>`<option value="${esc(r.id)}" ${r.id===edsRegion?'selected':''}>${esc(r.id)}${r.name?' · '+esc(r.name):''} — ${r.available?r.desktops+' desktop'+(r.desktops===1?'':'s'):'count unavailable'}</option>`).join('');
 const shortcuts=edsRegions.filter(r=>r.available&&r.desktops>0).map(r=>`<button type="button" class="region-shortcut ${r.id===edsRegion?'active':''}" data-action="eds-region" data-id="${esc(r.id)}" aria-pressed="${r.id===edsRegion}"><span>${esc(r.id)}</span><strong>${r.desktops}</strong></button>`).join('');
 return `<div class="toolbar provider-toolbar"><label class="region-select" for="eds-region-select">EDS region<select id="eds-region-select" required>${options}</select></label>${shortcuts?`<div class="region-shortcuts" aria-label="Regions with EDS desktops">${shortcuts}</div>`:''}</div>`;
}
function edsTableHTML(){
 const text=edsQuery.trim().toLowerCase();
 let items=records.filter(d=>(!text||[d.DesktopName,d.DesktopId,d.DesktopType,d.BundleName,d.PolicyGroupName,...(d.EndUserIds||[])].some(v=>String(v||'').toLowerCase().includes(text)))&&(!edsState||String(d.DesktopStatus||'').toLowerCase()===edsState)&&(!edsBilling||d.ChargeType===edsBilling));
 const key={name:d=>d.DesktopName||d.DesktopId,status:d=>d.DesktopStatus,type:d=>d.DesktopType||d.BundleName,billing:d=>d.ChargeType,expires:d=>d.ExpiredTime}[edsSort]||((d)=>d.DesktopName);
 items=[...items].sort((a,b)=>String(key(a)||'').localeCompare(String(key(b)||''),undefined,{numeric:true})*(edsDirection==='desc'?-1:1));
 const states=[...new Set(records.map(d=>String(d.DesktopStatus||'').toLowerCase()).filter(Boolean))].sort();
 const filters=`<form id="eds-filters" class="toolbar eds-toolbar"><input name="q" aria-label="Search EDS desktops" placeholder="Search name, ID, type, policy, or user…" value="${esc(edsQuery)}"><select name="state" aria-label="EDS desktop status"><option value="">All statuses</option>${states.map(s=>`<option value="${esc(s)}" ${s===edsState?'selected':''}>${esc(s)}</option>`).join('')}</select><select name="billing" aria-label="EDS billing method"><option value="">All billing</option><option value="PostPaid" ${edsBilling==='PostPaid'?'selected':''}>Pay-as-you-go</option><option value="PrePaid" ${edsBilling==='PrePaid'?'selected':''}>Subscription</option></select><select name="sort" aria-label="Sort EDS desktops"><option value="name" ${edsSort==='name'?'selected':''}>Sort: name</option><option value="status" ${edsSort==='status'?'selected':''}>Sort: status</option><option value="type" ${edsSort==='type'?'selected':''}>Sort: type</option><option value="billing" ${edsSort==='billing'?'selected':''}>Sort: billing</option><option value="expires" ${edsSort==='expires'?'selected':''}>Sort: expiry</option></select><select name="direction" aria-label="Sort direction"><option value="asc" ${edsDirection==='asc'?'selected':''}>Ascending</option><option value="desc" ${edsDirection==='desc'?'selected':''}>Descending</option></select><button class="secondary">Apply</button></form>`;
 const showRegion=edsRegion==='all';
 const rows=items.map(d=>{const status=String(d.DesktopStatus||'unknown').toLowerCase(),targetRegion=desktopRegion(d);const lifecycle=status==='running'?iconButton('stop','Stop desktop','eds-stop','danger',d.DesktopId,targetRegion):status==='stopped'?iconButton('start','Start desktop','eds-start','lifecycle-start',d.DesktopId,targetRegion):'';return `<tr><td><strong>${esc(d.DesktopName||d.DesktopId)}</strong><small>${esc(d.DesktopId)}</small></td><td><div class="status-control">${badge(status)}${lifecycle}</div></td><td><strong>${esc(d.DesktopType||d.BundleName||'—')}</strong><small>${esc(d.PolicyGroupName||'No policy name')}</small></td>${showRegion?`<td>${esc(targetRegion)}</td>`:''}<td>${esc(d.ChargeType||'—')}</td><td>${esc((d.EndUserIds||[]).join(', ')||'—')}</td><td>${esc(d.ExpiredTime||'—')}</td><td>${iconButton('manage','Manage desktop','eds-manage','manage-action',d.DesktopId,targetRegion)}</td></tr>`;});
 const warning=edsFailedRegions.length?`<div class="inline-warning">Some regions could not be loaded: ${esc(edsFailedRegions.join(', '))}</div>`:'';
 const headers=['DESKTOP','STATUS','TYPE / POLICY',...(showRegion?['REGION']:[]),'BILLING','USERS','EXPIRES',''];
 return `<div id="eds-table-panel" class="panel"><div class="panel-heading"><div><h2>Cloud desktops <span class="count">${items.length} / ${records.length}</span></h2><p>Live data from WUYING Elastic Desktop Service.</p></div><span class="muted">REGION · ${esc(edsRegion)}</span></div>${warning}${filters}${items.length?table(headers,rows):empty(records.length?'No matching desktops':showRegion?'No EDS desktops in any region':'No EDS desktops in this region',records.length?'Change or clear the table filters.':showRegion?'Select a specific region to create a desktop.':'Create a desktop or select another Alibaba region.',records.length||showRegion?'':button('+ Create desktop','eds-create'))}</div>`;
}
async function edsDesktopsPage(){
 if(!selectedAccount)return empty('Select an Alibaba account','Choose a cloud account from the sidebar.');
 edsRegion=edsRegion||preferredEDSRegion();
 let desktopResult;try{desktopResult=await api(edsPath('/desktops'));}catch(error){const actions=edsRegion==='all'?'':button('+ Create desktop','eds-create');const shell=heading('ALIBABA CLOUD / WUYING','EDS desktops',`Create and operate cloud desktops in ${esc(selectedAccount.name)}.`,actions)+edsRegionBar(true);return shell+`<div class="panel">${empty('Unable to load EDS',esc(error.message))}</div>`;}records=desktopResult.data;edsFailedRegions=desktopResult.failed_regions||[];try{edsRegions=(await api(`/accounts/${selectedAccount.id}/eds/regions`)).data;}catch{edsRegions=[...new Set([...(selectedAccount.regions||[]),...(selectedAccount.discovered_regions||[]),edsRegion].filter(id=>id&&id!=='all'))].sort().map(id=>({id,name:'',desktops:id===edsRegion?records.length:-1,available:id===edsRegion}))}if(edsRegion!=='all'){try{users=(await api(edsPath('/users'))).data;}catch{users=[];}}
 const actions=edsRegion==='all'?'<span class="muted">Select a region to create a desktop</span>':button('+ Create desktop','eds-create');
 return heading('ALIBABA CLOUD / WUYING','EDS desktops',`Create and operate cloud desktops in ${esc(selectedAccount.name)}.`,actions)+edsRegionBar(true)+edsTableHTML();
}
function userDesktopCount(userID){return edsAllDesktops.filter(d=>(d.EndUserIds||[]).includes(userID)).length;}
function edsUsersTableHTML(){
 const text=edsUserQuery.trim().toLowerCase();
 let items=records.filter(u=>(!text||[u.EndUserId,u.RealNickName,u.NickName,u.Email,u.WyId].some(v=>String(v||'').toLowerCase().includes(text)))&&(!edsUserStatus||String(u.Status??'unknown')===edsUserStatus)&&(!edsUserAdmin||(edsUserAdmin==='yes')===!!u.EnableAdminAccess));
 const key={id:u=>u.EndUserId,name:u=>u.RealNickName||u.NickName||u.EndUserId,email:u=>u.Email,status:u=>u.Status,desktops:u=>userDesktopCount(u.EndUserId)}[edsUserSort]||((u)=>u.EndUserId);
 items=[...items].sort((a,b)=>String(key(a)??'').localeCompare(String(key(b)??''),undefined,{numeric:true})*(edsUserDirection==='desc'?-1:1));
 const statuses=[...new Set(records.map(u=>String(u.Status??'unknown')))].sort();
 const filters=`<form id="eds-user-filters" class="toolbar eds-toolbar"><input name="q" aria-label="Search EDS users" placeholder="Search user ID, name, email, or WUYING ID…" value="${esc(edsUserQuery)}"><select name="status" aria-label="EDS user status"><option value="">All statuses</option>${statuses.map(s=>`<option value="${esc(s)}" ${s===edsUserStatus?'selected':''}>${esc(s)}</option>`).join('')}</select><select name="admin" aria-label="Local administrator access"><option value="">All access levels</option><option value="yes" ${edsUserAdmin==='yes'?'selected':''}>Local admin</option><option value="no" ${edsUserAdmin==='no'?'selected':''}>Standard user</option></select><select name="sort" aria-label="Sort EDS users"><option value="id" ${edsUserSort==='id'?'selected':''}>Sort: user ID</option><option value="name" ${edsUserSort==='name'?'selected':''}>Sort: display name</option><option value="email" ${edsUserSort==='email'?'selected':''}>Sort: email</option><option value="status" ${edsUserSort==='status'?'selected':''}>Sort: status</option><option value="desktops" ${edsUserSort==='desktops'?'selected':''}>Sort: desktops</option></select><select name="direction" aria-label="Sort direction"><option value="asc" ${edsUserDirection==='asc'?'selected':''}>Ascending</option><option value="desc" ${edsUserDirection==='desc'?'selected':''}>Descending</option></select><button class="secondary">Apply</button></form>`;
 const rows=items.map(u=>`<tr><td><strong>${esc(u.EndUserId)}</strong><small>${esc(u.WyId||'')}</small></td><td>${esc(u.RealNickName||u.NickName||'—')}</td><td>${esc(u.Email||'—')}</td><td>${badge(String(u.Status??'unknown'))}</td><td>${u.EnableAdminAccess?'Yes':'No'}</td><td>${button(String(userDesktopCount(u.EndUserId)),'eds-user-desktops','binding-count',u.EndUserId)}</td></tr>`);
 const warning=edsAssignmentsError?`<div class="inline-warning">${esc(edsAssignmentsError)}</div>`:edsFailedRegions.length?`<div class="inline-warning">Desktop assignments may be incomplete because these regions could not be loaded: ${esc(edsFailedRegions.join(', '))}</div>`:'';
 return `<div id="eds-users-table-panel" class="panel"><div class="panel-heading"><div><h2>Convenience accounts <span class="count">${items.length} / ${records.length}</span></h2><p>Users and desktop assignments across every EDS region.</p></div><span class="muted">WUYING DIRECTORY</span></div>${warning}${filters}${items.length?table(['USER ID','DISPLAY NAME','EMAIL','STATUS','LOCAL ADMIN','DESKTOPS'],rows):empty(records.length?'No matching users':'No EDS users yet',records.length?'Change or clear the table filters.':'Create a convenience account, then bind it to a desktop.',records.length?'':button('+ Create EDS user','eds-user-create'))}</div>`;
}
async function edsUsersPage(){
 if(!selectedAccount)return empty('Select an Alibaba account','Choose a cloud account from the sidebar.');
 if(!edsRegion||edsRegion==='all')edsRegion=preferredEDSRegion();
 if(!edsRegions.length){try{edsRegions=(await api(`/accounts/${selectedAccount.id}/eds/regions`)).data;}catch{edsRegions=[];}}
 const shell=heading('ALIBABA CLOUD / DIRECTORY','EDS users',`Convenience accounts for ${esc(selectedAccount.name)}.`,button('+ Create EDS user','eds-user-create'))+edsRegionBar();
 try{records=(await api(edsPath('/users'))).data;}catch(error){return shell+`<div class="panel">${empty('Unable to load EDS users',esc(error.message)+' Check the selected directory region and RAM permissions.')}</div>`;}
 try{const desktopResult=await api(edsPath('/desktops','all'));edsAllDesktops=desktopResult.data;edsFailedRegions=desktopResult.failed_regions||[];edsAssignmentsError='';}catch(error){edsAllDesktops=[];edsFailedRegions=[];edsAssignmentsError='Desktop assignments are unavailable: '+error.message;}
 return shell+edsUsersTableHTML();
}
async function edsCreateForm(){
 if(edsRegion==='all'){toast('Select a specific region before creating a desktop.');return;}
 const [catalog,userResult]=await Promise.all([api(edsPath('/catalog')),api(edsPath('/users'))]);users=userResult.data;
 edsCreateCatalog=catalog;
 const options=(items,value,label)=>items.map(item=>`<option value="${esc(item[value])}">${esc(item[label]||item[value])}</option>`).join('');
 const customReady=(catalog.desktop_types||[]).length&&(catalog.images||[]).length;
 modal('Create EDS desktop',`<form id="eds-desktop-form"><p class="cost-warning"><strong>This operation can create billable Alibaba Cloud resources.</strong><br>Review the billing mode and enable payment only when intended.</p><label>Desktop name<input name="name" required maxlength="64"></label><div class="split-form"><label>Office site<select name="office_site_id" required>${options(catalog.office_sites,'OfficeSiteId','Name')}</select></label><div class="bundle-field"><label>Desktop bundle<select name="bundle_id">${options(catalog.bundles,'BundleId','BundleName')}<option value="">Custom configuration</option></select></label><button type="button" class="secondary compact-action" data-action="eds-customize" ${customReady?'':'disabled'} title="${customReady?'Choose CPU, RAM, image and disks':'Custom catalog unavailable; update Alibaba RAM permissions'}">Customize</button></div></div><div id="custom-config-summary" class="custom-config-summary" hidden></div><input type="hidden" name="desktop_type"><input type="hidden" name="image_id"><input type="hidden" name="default_language"><input type="hidden" name="system_disk_size"><input type="hidden" name="data_disk_size"><div class="split-form"><label>Billing<select name="charge_type"><option value="PostPaid">Pay-as-you-go</option><option value="PrePaid">Subscription</option></select></label><label>Amount<input name="amount" type="number" min="1" max="10" value="1" required></label><label>Subscription period<input name="period" type="number" min="1" max="60" value="1"></label><label>Period unit<select name="period_unit"><option value="Month">Month</option><option value="Year">Year</option></select></label></div><label>Assign users now (optional)<select name="end_user_ids" multiple size="4">${options(users,'EndUserId','EndUserId')}</select></label><div class="split-form"><label>Hostname (optional)<input name="hostname" minlength="2" maxlength="15" pattern="[A-Za-z0-9](?:[A-Za-z0-9-]{0,13}[A-Za-z0-9])?" placeholder="desktop-01"></label><label>Security policy (optional)<select name="policy_group_id"><option value="">Use Alibaba default</option>${options(catalog.policy_groups,'PolicyGroupId','Name')}</select></label></div><label class="check"><input type="checkbox" name="auto_pay">Charge the Alibaba account automatically</label><label class="check"><input type="checkbox" name="auto_renew">Enable automatic renewal</label><label class="check confirm-check"><input type="checkbox" name="confirm_cost" required>I understand this request can incur charges</label><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button type="submit" class="primary">Create desktop</button></div></form>`);
}
function customDesktopForm(){
 const types=(edsCreateCatalog?.desktop_types||[]).filter(t=>t.DesktopTypeId&&t.CpuCount&&t.MemorySize),images=(edsCreateCatalog?.images||[]).filter(i=>i.ImageId&&i.OsType);
 if(!types.length||!images.length){toast('Custom desktop options are unavailable. Check DescribeDesktopTypes and DescribeImages permissions.');return;}
 const unique=(items,key)=>[...new Set(items.map(item=>String(item[key])).filter(Boolean))].sort((a,b)=>Number(a)-Number(b)||a.localeCompare(b));
 const cpus=unique(types,'CpuCount'),oses=unique(images,'OsType');
 $('#custom-modal-body').innerHTML=`<form id="eds-custom-form"><p class="muted">CPU and RAM select an available Alibaba desktop type. Disk sizes are in GiB.</p><div class="split-form"><label>vCPU<select name="cpu">${cpus.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label>RAM (MiB)<select name="memory"></select></label><label>Operating system<select name="os">${oses.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label>Image<select name="image_id"></select></label><label>System disk<input name="system_disk_size" type="number" min="60" max="500" step="10" value="80" required></label><label>Language<select name="default_language"><option value="en-US">English</option><option value="zh-CN">Simplified Chinese</option><option value="zh-HK">Traditional Chinese</option><option value="ja-JP">Japanese</option></select></label></div><label class="check"><input id="custom-data-disk" name="add_data_disk" type="checkbox">Add data disk</label><label id="custom-data-disk-size" hidden>Data disk size (GiB)<input name="data_disk_size" type="number" min="40" max="2040" step="10" value="40"></label><div id="custom-type-summary" class="custom-type-summary"></div><p id="custom-form-error" class="error"></p><div class="form-actions"><button type="button" class="secondary" data-action="close-custom">Cancel</button><button type="submit" class="primary">Use configuration</button></div></form>`;
 syncCustomOptions('cpu');$('#custom-modal').showModal();
}
function syncCustomOptions(changed){
 const form=$('#eds-custom-form');if(!form)return;const types=edsCreateCatalog.desktop_types||[],images=edsCreateCatalog.images||[];
 if(changed==='cpu'){const current=form.memory.value,memories=[...new Set(types.filter(t=>String(t.CpuCount)===form.cpu.value).map(t=>String(t.MemorySize)))].sort((a,b)=>Number(a)-Number(b));form.memory.innerHTML=memories.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
 if(changed==='os'||!form.image_id.options.length){const current=form.image_id.value;form.image_id.innerHTML=images.filter(i=>String(i.OsType)===form.os.value).map(i=>`<option value="${esc(i.ImageId)}" ${i.ImageId===current?'selected':''}>${esc(i.Name||i.ImageId)} · ${esc(i.OsName||i.OsType)}</option>`).join('');}
 const type=types.find(t=>String(t.CpuCount)===form.cpu.value&&String(t.MemorySize)===form.memory.value);$('#custom-type-summary').textContent=type?`${type.DesktopTypeId} · ${type.CpuCount} vCPU · ${type.MemorySize} MiB RAM`:'No matching desktop type';
}
